#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n;
    cin >> n;
    int tot = 3*n;
    vector<long long> ss(tot+1);
    for (int i = 1; i <= tot; i++) {
        cin >> ss[i];
    }
    sort(ss.begin()+1, ss.end(), greater<long long>());
    vector<long long> p(tot+1, 0);
    for (int i = 1; i <= tot; i++) {
        p[i] = p[i-1]+ss[i];
    }
    long long maxans = 0;
    for (int a = 0; a <= n; a++) {
        int l = 0, r = n-a-1, best = 0;
        while (l <= r) {
            int mid = l+(r-l)/2, idx1 = a+2*mid+1, idx2 = a+2*mid+2, idx3 = 3*n-2*a-mid;
            long long diff = ss[idx1]+ss[idx2]-3*ss[idx3];
            if (diff >= 0) {
                best = mid+1;
                l = mid+1;
            } else {
                r = mid-1;
            }
        }
        int st = max(0, best-2), en = min(n-a, best+2);
        for (int b = st; b <= en; b++) {
            long long score = 2*p[a]+p[a+2*b]+3*p[3*n-2*a-b];
            if (score > maxans) {
                maxans = score;
            }
        }
    }
    cout << maxans << endl;
}

int main() {
    int t;
    cin >> t;
    while(t--) solve();
    

}
